const FILE = 'XXCDf1exA9gaD416aklfjm';
const out = [];
for (const it of $input.all()) {
  const b = (it.json && it.json.body) ? it.json.body : (it.json || {});
  for (const s of (b.items || [])) {
    out.push({ json: {
      project_id: String(s.project_id || ''),
      url: String(s.url || ''),
      title: String(s.title || ''),
      description: String(s.description || ''),
      key_ids: (s.key_ids || []).map(function (x) { return Number(x); }),
      tags: s.tags || ['figma'],
      ocr: s.ocr === true
    } });
  }
  const spec = String(b.spec || '');
  if (spec) {
    for (const line of spec.split('\n')) {
      const t = line.trim();
      if (!t) continue;
      const p = t.split(';');
      if (p.length < 5) continue;
      const nodeId = p[1].trim();
      const title = p[2].trim();
      const page = nodeId.indexOf('7566') === 0 ? 'Emails' : 'Ready for Dev';
      const ids = [];
      for (const x of p[4].split(',')) { const n = Number(x.trim()); if (n) ids.push(n); }
      out.push({ json: {
        project_id: p[0].trim(),
        url: p[3].trim(),
        title: title,
        description: 'Figma · ' + page + ' · ' + title + ' — https://www.figma.com/design/' + FILE + '/ChatbotOnline?node-id=' + nodeId.replace(':', '-'),
        key_ids: ids,
        tags: ['figma'],
        ocr: false
      } });
    }
  }
}
return out;

const meta = $('Explode Items').all();
const rows = $input.all();
const out = [];
for (let i = 0; i < rows.length; i++) {
  const pi = rows[i].pairedItem;
  let idx = i;
  if (pi && typeof pi === 'object' && typeof pi.item === 'number') { idx = pi.item; }
  else if (typeof pi === 'number') { idx = pi; }
  const m = (meta[idx] || meta[i] || {}).json || {};
  let b64 = '';
  let how = '';
  try {
    const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
    if (buf && buf.length) { b64 = buf.toString('base64'); how = 'buffer'; }
  } catch (e) {
    how = 'err:' + String(e && e.message ? e.message : e).slice(0, 120);
  }
  if (!b64) {
    const bin = rows[i].binary || {};
    const d = bin.data || {};
    if (d.data && !d.id) { b64 = d.data; how = 'inline'; }
  }
  if (!b64) {
    out.push({ json: { skipped: true, reason: 'no image bytes (' + how + ')', title: m.title, url: m.url, project_id: m.project_id, key_ids: m.key_ids } });
    continue;
  }
  out.push({ json: {
    project_id: m.project_id,
    title: m.title,
    description: m.description,
    key_ids: m.key_ids,
    tags: m.tags,
    ocr: m.ocr,
    how: how,
    bytes: Math.round((b64.length * 3) / 4),
    dataUri: 'data:image/png;base64,' + b64,
    skipped: false
  } });
}
return out;

const meta = $('Build Upload Payload').all();
const rows = $input.all();
const ok = [];
const bad = [];
for (let i = 0; i < rows.length; i++) {
  const pi = rows[i].pairedItem;
  let idx = i;
  if (pi && typeof pi === 'object' && typeof pi.item === 'number') { idx = pi.item; }
  else if (typeof pi === 'number') { idx = pi; }
  const m = (meta[idx] || meta[i] || {}).json || {};
  const r = rows[i].json || {};
  const body = r.body || {};
  const shot = (body.screenshots && body.screenshots[0]) ? body.screenshots[0] : null;
  if (r.statusCode === 200 && shot) {
    ok.push({ title: m.title, screenshot_id: shot.screenshot_id, keys: (m.key_ids || []).length, bytes: m.bytes });
  } else {
    bad.push({ title: m.title, status: r.statusCode, error: JSON.stringify(body).slice(0, 300), keys: (m.key_ids || []).length });
  }
}
return [{ json: { uploaded: ok.length, failed: bad.length, ok: ok, bad: bad } }];
